  method: "POST",
  credentials: "omit",
  headers: {
  "Accept": "application/json",
  "Authorization": "Bearer YOUR_ACCESS_TOKEN",
  "Idempotency-Key": "exemplu-programContributorWithdraw-001",
  "Content-Type": "application/json"
},
  body: JSON.stringify({})
});
const result = await response.json();
if (!response.ok) throw new Error(result.message || result.error_description || ('HTTP ' + response.status));
console.log(result);
```

### Python

```python
import json, urllib.request, urllib.parse, urllib.error

headers = {'Accept': 'application/json', 'Authorization': 'Bearer YOUR_ACCESS_TOKEN', 'Idempotency-Key': 'exemplu-programContributorWithdraw-001', 'Content-Type': 'application/json'}
payload = json.loads('{}')
data = json.dumps(payload).encode("utf-8")
request = urllib.request.Request('https://openaliment.ro/api/v2/program/me/contributors/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/withdraw', data=data, headers=headers, method='POST')
try:
    with urllib.request.urlopen(request, timeout=15) as response:
        print(json.load(response))
except urllib.error.HTTPError as error:
    print(error.code, error.read().decode("utf-8", errors="replace"))
    raise
```

